macro.command:
// 磁轭手铳 Lodestone Hand-Cannon — 物品宏 [postActiveEffects]
// 命中后：消耗 1 次磁轭牵引（每长休 = 熟练加值 次）→ 点地图选方向 → 目标体质豁免 → 失败则被牵引最多 15 尺。
// 落点/碰撞玩家端只读计算；移动与对敌伤害交 GM 端 LHGM。
(async () => {
  const me = canvas.tokens.controlled[0] ?? (typeof token !== "undefined" ? token : null);
  if (!me) return;

  const wf = (typeof workflow !== "undefined" && workflow) ? workflow
    : ((typeof MidiQOL !== "undefined") ? (MidiQOL.currentWorkflow ?? null) : null);
  const target = Array.from(wf?.hitTargets ?? [])[0]
    ?? Array.from(wf?.targets ?? [])[0]
    ?? Array.from(game.user.targets ?? [])[0] ?? null;
  if (!target) return;                       // 未命中/无目标 → 不触发
  const myItem = wf?.item ?? wf?.activity?.item ?? wf?.rolledItem ?? (typeof item !== "undefined" ? item : null);

  // 次数限制：max = @prof，每长休回满
  const mrd = me.actor.getRollData();
  const profVal = Number(mrd.prof ?? mrd.attributes?.prof ?? 2);
  const dexMod = Number(mrd.abilities?.dex?.mod ?? 0);
  const maxUses = Math.max(1, profVal);
  const spent = Number(myItem?.system?.uses?.spent ?? 0);
  if (maxUses - spent <= 0) { ui.notifications.warn("磁轭手铳：牵引力竭，长休后回复使用次数。"); return; }

  const gridSize = canvas.grid.size;
  const ftPerSq = canvas.scene.grid?.distance ?? 5;
  const MAX_FT = 15;
  const maxCells = Math.max(1, Math.round(MAX_FT / ftPerSq));
  const cen = (tk) => ({ x: tk.center?.x ?? (tk.x + tk.w / 2), y: tk.center?.y ?? (tk.y + tk.h / 2) });
  const tc = cen(target);

  const SNAP = CONST.GRID_SNAPPING_MODES;
  const snapCenter = (p) => {
    try { return canvas.grid.getSnappedPoint({ x: p.x, y: p.y }, { mode: SNAP.CENTER, resolution: 1 }); }
    catch (e) { return { x: Math.round(p.x / gridSize) * gridSize, y: Math.round(p.y / gridSize) * gridSize }; }
  };
  const pickPoint = () => new Promise((resolve) => {
    const g = new PIXI.Graphics();
    g.lineStyle(2, 0x66ccff, 0.9); g.beginFill(0x66ccff, 0.05);
    g.drawCircle(tc.x, tc.y, maxCells * gridSize); g.endFill();
    g.zIndex = 10000; canvas.app.stage.addChild(g);
    ui.notifications.info(`左键点地图选牵引方向，右键取消（剩余 ${maxUses - spent} 次）`);
    const cleanup = () => { try { canvas.app.stage.off("pointerdown", h); } catch (e) {} try { canvas.app.stage.removeChild(g); } catch (e) {} };
    const h = (ev) => {
      const btn = ev.data?.originalEvent?.button ?? ev.data?.button ?? ev.button ?? 0;
      cleanup();
      if (btn === 2) return resolve(null);              // 右键取消
      let p = null; try { p = ev.data.getLocalPosition(canvas.app.stage); } catch (e) {}
      resolve(p ? snapCenter(p) : null);
    };
    canvas.app.stage.on("pointerdown", h);
    setTimeout(() => { cleanup(); resolve(null); }, 20000);
  });

  // 点方向（取消 = 不消耗次数）
  const pt = await pickPoint();
  if (!pt) return;
  let vx = pt.x - tc.x, vy = pt.y - tc.y;
  if (Math.hypot(vx, vy) < 1) return;        // 点在目标自身格 → 取消
  const len = Math.hypot(vx, vy) || 1; vx /= len; vy /= len;

  // 消耗 1 次（提交方向后）
  try { if (myItem) await myItem.update({ "system.uses.spent": spent + 1 }); } catch (e) { console.error("手铳 | 扣次数失败", e); }

  // 磁力束动画（无 Sequencer 则跳过）
  const hasSeq = !!game.modules.get("sequencer")?.active && typeof Sequence !== "undefined";
  const firstFound = (arr) => {
    if (!window.Sequencer?.Database) return null;
    for (const k of arr) { try { if (Sequencer.Database.entryExists(k)) return k; } catch (e) {} }
    return null;
  };
  const beam = hasSeq ? firstFound(["jb2a.energy_beam.normal.bluepink.03", "jb2a.chain_lightning.primary.blue", "jb2a.energy_strands.range.standard.blue.01", "jb2a.ranged.03.projectile.01.blue", "jb2a.lightning.03.blue"]) : null;
  if (beam) { try { await new Sequence().effect().atLocation(me).stretchTo(target).file(beam).play(); } catch (e) {} }

  // 体质豁免（用一定存在的基元自算：con调整值 + 已熟练?熟练:0；忽略杂项豁免加值）
  const trd = target.actor.getRollData();
  const conMod = Number(trd.abilities?.con?.mod ?? 0);
  const conProf = target.actor.system?.abilities?.con?.proficient ? profVal : 0;
  const conSave = conMod + conProf;
  const dc = 8 + profVal + dexMod;
  let saved = false;
  try {
    const sv = await (new Roll(`1d20 + ${conSave}`)).evaluate();
    await sv.toMessage({ flavor: `抵抗磁轭牵引 · 体质豁免 vs DC ${dc}`, speaker: ChatMessage.getSpeaker({ token: target.document }) });
    saved = sv.total >= dc;
  } catch (e) { console.error("手铳 | 豁免失败", e); }
  if (saved) { ui.notifications.info(`${target.name} 抵抗了磁轭牵引。`); return; }

  // 失败 → 沿方向牵引，找生物/墙碰撞
  const creatureAt = (c, ignore) => canvas.tokens.placeables.find((tk) => {
    if (ignore && tk.id === ignore.id) return false;
    return c.x >= tk.x && c.x < tk.x + tk.w && c.y >= tk.y && c.y < tk.y + tk.h;
  });
  const wallBetween = (a, b) => {                  // ⚠ 核心 API，字典未收录，实测；取不到则只靠生物碰撞
    try {
      const be = CONFIG.Canvas?.polygonBackends?.move;
      if (be?.testCollision) return !!be.testCollision({ x: a.x, y: a.y }, { x: b.x, y: b.y }, { type: "move", mode: "any" });
    } catch (e) {}
    return false;
  };

  let cur = { ...tc }, final = { ...tc }, collided = false, obstacleId = null;
  for (let i = 0; i < maxCells; i++) {
    const next = { x: cur.x + vx * gridSize, y: cur.y + vy * gridSize };
    const occ = creatureAt(next, target);
    if (occ) { collided = true; obstacleId = occ.id; break; }
    if (wallBetween(cur, next)) { collided = true; break; }
    cur = next; final = next;
  }

  if (collided && hasSeq) {
    const impact = firstFound(["jb2a.impact.010.blue", "jb2a.static_electricity.03.blue", "jb2a.impact.blue.0", "jb2a.impact.ground_crack.blue.01"]);
    if (impact) { try { await new Sequence().effect().atLocation({ x: final.x, y: final.y }).file(impact).scale(0.7).play(); } catch (e) {} }
  }

  // 移动 + 对敌伤害 → GM
  const tw = target.document?.width ?? 1, th = target.document?.height ?? 1;
  const moved = (final.x !== tc.x || final.y !== tc.y);
  const ops = [];
  if (moved) ops.push({ tokenId: target.id, move: { x: Math.round(final.x - (tw * gridSize) / 2), y: Math.round(final.y - (th * gridSize) / 2), animate: true } });
  if (collided) {
    try {
      const r = await (new Roll("2d6")).evaluate();
      await r.toMessage({ flavor: "磁轭撞击 Lodestone Slam（力场）", speaker: ChatMessage.getSpeaker({ actor: me.actor }) });
      ops.push({ tokenId: target.id, damage: [{ value: r.total, type: "force" }] });
    } catch (e) {}
    if (obstacleId && obstacleId !== me.id) {        // 撞到自己身边 → 不扣自己血
      try {
        const r2 = await (new Roll("1d6")).evaluate();
        await r2.toMessage({ flavor: "磁轭连撞（力场）", speaker: ChatMessage.getSpeaker({ actor: me.actor }) });
        ops.push({ tokenId: obstacleId, damage: [{ value: r2.total, type: "force" }] });
      } catch (e) {}
    }
  }
  if (ops.length) {
    if (globalThis.LHGM?.request) await globalThis.LHGM.request({ sceneId: canvas.scene.id, ops });
    else ui.notifications.warn("磁轭手铳：未加载 GM 代办脚本（LHGM）——位移/撞击伤害未生效。");
  }
})();
